css:
.container {
  width: 100%;
  height: 100%;
  background:
    linear-gradient(135deg, #4f46e5 25%, transparent 25%) -50px 0,
    linear-gradient(225deg, #4f46e5 25%, transparent 25%) -50px 0,
    linear-gradient(315deg, #4f46e5 25%, transparent 25%),
    linear-gradient(45deg, #4f46e5 25%, transparent 25%),
    linear-gradient(to bottom, #3b82f6 0%, #2563eb 100%);
  background-size:
    100px 100px,
    100px 100px,
    100px 100px,
    100px 100px,
    100% 100%;
  background-color: #1d4ed8;
  position: relative;
}

.container::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
      circle at 0% 0%,
      rgba(255, 255, 255, 0.2) 0%,
      transparent 50%
    ),
    radial-gradient(
      circle at 100% 0%,
      rgba(255, 255, 255, 0.2) 0%,
      transparent 50%
    ),
    radial-gradient(
      circle at 100% 100%,
      rgba(255, 255, 255, 0.2) 0%,
      transparent 50%
    ),
    radial-gradient(
      circle at 0% 100%,
      rgba(255, 255, 255, 0.2) 0%,
      transparent 50%
    );
  background-size: 50% 50%;
  background-position:
    0 0,
    100% 0,
    100% 100%,
    0 100%;
  background-repeat: no-repeat;
}
